/**
 * The physics engine — a code-split chunk.
 *
 * A registered chunk manifest module (MANIFEST_MODULES in
 * tooling/check-shader-imports.mjs, `chunk: true`): loaded exclusively by
 * dynamic `import()` from physics.ts, and only when a world asks for a rigid
 * body. The engine is Havok through Babylon's own plugin; its wasm ships with
 * the client and is fetched from the same origin, the first time a world
 * needs it. A world that never asks never pays for it.
 *
 * What this module knows: how to start the engine on a scene and how to make
 * and drive a body. What it does not know: entities, interaction states, the
 * visitor. Those are physics.ts's, in the main bundle, so the policy stays
 * small and testable without the engine.
 */
import '@babylonjs/core/Physics/joinedPhysicsEngineComponent';
import { HavokPlugin } from '@babylonjs/core/Physics/v2/Plugins/havokPlugin';
import { PhysicsAggregate } from '@babylonjs/core/Physics/v2/physicsAggregate';
import { PhysicsMotionType, PhysicsShapeType } from '@babylonjs/core/Physics/v2/IPhysicsEnginePlugin';
import type { PhysicsBody } from '@babylonjs/core/Physics/v2/physicsBody';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { TransformNode } from '@babylonjs/core/Meshes/transformNode';
import type { Mesh } from '@babylonjs/core/Meshes/mesh';
import type { Scene } from '@babylonjs/core/scene';

export type PhysicsMotion = 'dynamic' | 'static' | 'animated';

export interface PhysicsBodySpec {
  motion: PhysicsMotion;
  /** `convex` and `mesh` take their geometry from `mesh`; `box` from `extents`; `capsule` from `radius` and `height`. */
  shape: 'box' | 'convex' | 'mesh' | 'capsule';
  mass: number;
  mesh?: Mesh;
  extents?: Vector3;
  /** The shape's centre in the node's local frame (a box built from a hierarchy's bounds). */
  center?: Vector3;
  radius?: number;
  height?: number;
  friction?: number;
  restitution?: number;
  /** The body never turns: a character stands on its feet, as a character controller keeps it. */
  upright?: boolean;
}

export interface PhysicsBodyHandle {
  setMotion(motion: PhysicsMotion): void;
  motion(): PhysicsMotion;
  setMass(mass: number, centerOfMass?: Vector3): void;
  setDamping(linear?: number, angular?: number): void;
  setLinearVelocity(v: Vector3): void;
  linearVelocity(): Vector3;
  dispose(): void;
}

export interface PhysicsWorld {
  body(node: TransformNode, spec: PhysicsBodySpec): PhysicsBodyHandle;
  /** Advance the simulation by `dtS` (tests; in the client the scene's render step does this). */
  step(dtS: number): void;
  dispose(): void;
}

export interface CreatePhysicsWorldOptions {
  gravity: Vector3;
  /** The engine instance factory; the default fetches the wasm beside the chunk. Tests hand in bytes read from disk. */
  instantiate?: () => Promise<unknown>;
}

export type PhysicsChunkModule = {
  createPhysicsWorld(scene: Scene, options: CreatePhysicsWorldOptions): Promise<PhysicsWorld>;
};

const MOTION: Record<PhysicsMotion, PhysicsMotionType> = {
  dynamic: PhysicsMotionType.DYNAMIC,
  static: PhysicsMotionType.STATIC,
  animated: PhysicsMotionType.ANIMATED,
};

const defaultInstantiate = async (): Promise<unknown> => {
  const havok = (await import('@babylonjs/havok')).default;
  return havok();
};

function shapeType(spec: PhysicsBodySpec): PhysicsShapeType {
  switch (spec.shape) {
    case 'convex':
      return PhysicsShapeType.CONVEX_HULL;
    case 'mesh':
      return PhysicsShapeType.MESH;
    case 'capsule':
      return PhysicsShapeType.CAPSULE;
    default:
      return PhysicsShapeType.BOX;
  }
}

export async function createPhysicsWorld(scene: Scene, options: CreatePhysicsWorldOptions): Promise<PhysicsWorld> {
  const instance = await (options.instantiate ?? defaultInstantiate)();
  const plugin = new HavokPlugin(true, instance);
  if (!scene.enablePhysics(options.gravity.clone(), plugin)) {
    throw new Error('the scene refused the physics engine');
  }
  const engine = scene.getPhysicsEngine();
  if (!engine) throw new Error('the physics engine did not start');
  const bodies = new Set<PhysicsAggregate>();

  return {
    body(node, spec): PhysicsBodyHandle {
      const params: ConstructorParameters<typeof PhysicsAggregate>[2] = {
        mass: spec.motion === 'dynamic' ? Math.max(spec.mass, 0.001) : 0,
        friction: spec.friction ?? 0.6,
        restitution: spec.restitution ?? 0.1,
      };
      if (spec.mesh) params.mesh = spec.mesh;
      if (spec.extents) params.extents = spec.extents;
      if (spec.center) params.center = spec.center;
      if (spec.radius !== undefined) params.radius = spec.radius;
      if (spec.height !== undefined && spec.radius !== undefined) {
        // A capsule from its feet: the segment between the two sphere centres.
        params.pointA = new Vector3(0, spec.radius, 0);
        params.pointB = new Vector3(0, Math.max(spec.radius, spec.height - spec.radius), 0);
      }
      const aggregate = new PhysicsAggregate(node, shapeType(spec), params, scene);
      bodies.add(aggregate);
      const body: PhysicsBody = aggregate.body;
      body.setMotionType(MOTION[spec.motion]);
      // The node is the authority a script writes to: a position set on it
      // reaches the body before the next step. The step writes back after.
      body.disablePreStep = false;
      let motion: PhysicsMotion = spec.motion;
      let mass = Math.max(spec.mass, 0.001);
      let centerOfMass: Vector3 | undefined;
      const velocity = new Vector3();
      // No inertia, so no torque turns it: the engine's way to keep a body upright.
      const applyMass = (): void => {
        body.setMassProperties({
          mass,
          ...(centerOfMass ? { centerOfMass: centerOfMass.clone() } : {}),
          ...(spec.upright ? { inertia: Vector3.Zero() } : {}),
        });
      };
      if (spec.upright && spec.motion === 'dynamic') applyMass();
      return {
        setMotion(next): void {
          motion = next;
          body.setMotionType(MOTION[next]);
          // A body that was kinematic or static has no mass of its own; a
          // dynamic one needs it back, or it does not move.
          if (next === 'dynamic') applyMass();
          else body.setLinearVelocity(Vector3.Zero());
        },
        motion: () => motion,
        setMass(nextMass, nextCenter): void {
          mass = Math.max(nextMass, 0.001);
          if (nextCenter) centerOfMass = nextCenter.clone();
          if (motion === 'dynamic') applyMass();
        },
        setDamping(linear, angular): void {
          if (linear !== undefined) body.setLinearDamping(Math.max(0, linear));
          if (angular !== undefined) body.setAngularDamping(Math.max(0, angular));
        },
        setLinearVelocity(v): void {
          body.setLinearVelocity(v);
        },
        linearVelocity(): Vector3 {
          body.getLinearVelocityToRef(velocity);
          return velocity.clone();
        },
        dispose(): void {
          if (!bodies.delete(aggregate)) return;
          aggregate.dispose();
        },
      };
    },
    step(dtS): void {
      (engine as unknown as { _step(dt: number): void })._step(dtS);
    },
    dispose(): void {
      for (const b of bodies) b.dispose();
      bodies.clear();
      scene.disablePhysicsEngine();
    },
  };
}
